ALTER TABLE public.promo_markets DROP CONSTRAINT IF EXISTS promo_markets_product_check;
ALTER TABLE public.promo_markets ADD CONSTRAINT promo_markets_product_check CHECK (product IN ('routing', 'uitgelicht', 'topplek'));
ALTER TABLE public.promo_markets ALTER COLUMN dish_id DROP NOT NULL;
ALTER TABLE public.promo_markets ADD COLUMN IF NOT EXISTS page_slug text;
CREATE UNIQUE INDEX IF NOT EXISTS promo_markets_page ON public.promo_markets (product, page_slug) WHERE page_slug IS NOT NULL;
ALTER TABLE public.package_orders DROP CONSTRAINT IF EXISTS package_orders_package_check;
ALTER TABLE public.package_orders ADD CONSTRAINT package_orders_package_check CHECK (package IN ('founding_partner', 'menu_service', 'topplek', 'groei', 'dominant'));
ALTER TABLE public.package_orders DROP CONSTRAINT IF EXISTS package_orders_founding_page_check;
ALTER TABLE public.package_orders ADD CONSTRAINT package_orders_founding_page_check CHECK (package = 'menu_service' OR page_slug IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_package_orders_page_all ON public.package_orders (page_slug, package) WHERE page_slug IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.paid_stats_daily (restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE, page_slug text NOT NULL, surface text NOT NULL CHECK (surface IN ('gerechtpagina', 'zoeken', 'kaart', 'homepage', 'badge', 'spotlight')), dag date NOT NULL DEFAULT ((now() AT TIME ZONE 'Europe/Amsterdam')::date), metric text NOT NULL CHECK (metric IN ('impressie', 'klik')), n integer NOT NULL DEFAULT 0, PRIMARY KEY (restaurant_id, page_slug, surface, dag, metric));
GRANT ALL ON public.paid_stats_daily TO service_role;
ALTER TABLE public.paid_stats_daily ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.paid_stats_daily FROM anon, authenticated;
CREATE TABLE IF NOT EXISTS public.spotlight_bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE, user_id uuid, city_id uuid NOT NULL REFERENCES public.cities(id) ON DELETE CASCADE, week_start date NOT NULL, headline text NOT NULL CHECK (char_length(headline) BETWEEN 2 AND 40), body text NOT NULL CHECK (char_length(body) BETWEEN 2 AND 160), status text NOT NULL DEFAULT 'pending_payment' CHECK (status IN ('pending_payment', 'active', 'cancelled')), reserved_until timestamptz, amount_cents int NOT NULL DEFAULT 3900, stripe_session_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.spotlight_bookings TO authenticated;
GRANT ALL ON public.spotlight_bookings TO service_role;
CREATE UNIQUE INDEX IF NOT EXISTS spotlight_one_per_week ON public.spotlight_bookings (restaurant_id, week_start) WHERE status IN ('pending_payment', 'active');
CREATE INDEX IF NOT EXISTS spotlight_city_week ON public.spotlight_bookings (city_id, week_start, status);
ALTER TABLE public.spotlight_bookings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Owners view their spotlight bookings" ON public.spotlight_bookings;
CREATE POLICY "Owners view their spotlight bookings" ON public.spotlight_bookings FOR SELECT USING (auth.uid() IS NOT NULL AND public.is_verified_owner(auth.uid(), restaurant_id));
DROP POLICY IF EXISTS "Admins manage spotlight bookings" ON public.spotlight_bookings;
CREATE POLICY "Admins manage spotlight bookings" ON public.spotlight_bookings FOR ALL USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
ALTER TABLE public.newsletter_placements ADD COLUMN IF NOT EXISTS edition_date date;
ALTER TABLE public.newsletter_editions ADD COLUMN IF NOT EXISTS city_id uuid REFERENCES public.cities(id) ON DELETE SET NULL;
ALTER TABLE public.newsletter_editions ADD COLUMN IF NOT EXISTS edition_date date;
CREATE INDEX IF NOT EXISTS newsletter_placements_city_date ON public.newsletter_placements (target_city_id, edition_date);
CREATE TABLE IF NOT EXISTS public.test_visit_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE, user_id uuid, status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'planned', 'visited', 'approved', 'rejected', 'withdrawn')), owner_note text CHECK (owner_note IS NULL OR char_length(owner_note) <= 500), feedback text, admin_note text, visited_on date, created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.test_visit_requests TO authenticated;
GRANT ALL ON public.test_visit_requests TO service_role;
CREATE INDEX IF NOT EXISTS test_visit_requests_restaurant ON public.test_visit_requests (restaurant_id, created_at DESC);
ALTER TABLE public.test_visit_requests ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Owners view their test visits" ON public.test_visit_requests;
CREATE POLICY "Owners view their test visits" ON public.test_visit_requests FOR SELECT USING (auth.uid() IS NOT NULL AND public.is_verified_owner(auth.uid(), restaurant_id));
DROP POLICY IF EXISTS "Admins manage test visits" ON public.test_visit_requests;
CREATE POLICY "Admins manage test visits" ON public.test_visit_requests FOR ALL USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
ALTER TABLE public.collection_restaurants ADD COLUMN IF NOT EXISTS tested_at date;